const isOneOfCardFieldsFilled = (form) => {
  const participantData = form.getFieldsValue()
  const { policy_number: policy, card_number: cardNo, company_name: companyName } = participantData?.employee_data?.policy_data || {}
  return policy || cardNo || companyName
}

export const editEmployeeValidations = {
  policy_number: (form) => [
    {
      required: isOneOfCardFieldsFilled(form),
      message: 'Policy Number is Required'
    },
    {
      max: 27,
      message: 'Policy Number Cannot be more than 27 characters'
    }
  ],
  card_number: (form) => [
    {
      required: isOneOfCardFieldsFilled(form),
      message: 'Card Number is required'
    }
  ],
  company_name: (form) => [
    {
      required: isOneOfCardFieldsFilled(form),
      message: 'E-Card company name is required'
    }
  ]
}
