/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import {
  Typography,
  Spin,
  Col,
  Button,
  Form,
  Input,
  Select,
  DatePicker,
  Divider,
  Alert
} from 'antd'
import moment from 'moment'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { RowWithMargin } from '../../../CommonComponents/index'
import { ColTextAlignCenter } from '../../../CommonComponents/index.style'
import { EmployeeFormItemConfigs, formattedPhoneNumber } from './constant'
import { useUpdateEmployee } from '../../../state/EditEmployee/hooks/useEditEmployee'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useResetState } from '../../../state/hooks'
import { editEmployeeValidations } from './validations'

const { Title } = Typography
const { Option } = Select

const EmployeeDetail = ({ history, match, location, form, ...props }) => {
  const { updateEmployeeData, updateEmployeeRequest } = useUpdateEmployee()
  const [{ UPDATE_EMPLOYEE_ERROR, updateEmployeeStatus, updateEmployeeErrorData }] = useErrorContextValue()
  const [{ UPDATE_EMPLOYEE_LOADER }] = useLoaderContextValue()
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const { getFieldDecorator } = form
  const employeeData = location?.state || {}
  const isRequired = !!(employeeData.status === 'UNPAID' || employeeData.effective_join_date)

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      const valuesToBeSent = {
        employee_data: {
          ...values.employee_data,
          phone: values.employee_data.phone ? '62-' + values.employee_data.phone : null,
          dob: values.employee_data.dob ? values.employee_data.dob.format('YYYY-MM-DD') : '',
          effective_join_date: values.employee_data.effective_join_date ? values.employee_data.effective_join_date.format('YYYY-MM-DD') : undefined,
          email: values.employee_data.email ? values.employee_data.email : null
        },
        employee_id: match.params.employeeId,
        company_id: match.params.companyId
      }
      if (!(Object.values(values.employee_data.policy_data).reduce((prevValue, value) => prevValue || !!value))) {
        delete valuesToBeSent.employee_data.policy_data
      }

      if (!err) {
        updateEmployeeRequest(valuesToBeSent)
        resetState(['updateEmployeeData', 'updateEmployeeStatus'])
        resetError(['updateEmployeeData', 'updateEmployeeStatus', 'UPDATE_EMPLOYEE_ERROR'])
      }
    })
  }

  useEffect(() => {
    if (UPDATE_EMPLOYEE_ERROR) {
      if (updateEmployeeErrorData && updateEmployeeErrorData.error) {
        const error = updateEmployeeErrorData.error
        for (const key in error) {
          const values = form.getFieldsValue()
          if (['policy_number', 'company_name', 'card_number'].includes(key)) {
            form.setFields({
              [`employee_data.policy_data.${key}`]: {
                value: values.employee?.policy_data?.[key],
                errors: Array.isArray(error.employee?.policy_data?.[key]) ? error.employee?.policy_data?.[key].map(err => new Error(err)) : null
              }
            })
            continue
          }
          form.setFields({
            [`employee_data.${key}`]: {
              value: values.employee_data[key],
              errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
            }
          })
        }
      }
    }
  }, [UPDATE_EMPLOYEE_ERROR, updateEmployeeStatus, updateEmployeeData])

  useEffect(() => {
    if (!UPDATE_EMPLOYEE_ERROR && updateEmployeeData && updateEmployeeData.employee_data) {
      resetState(['updateEmployeeData', 'updateEmployeeStatus'])
      resetError(['UPDATE_EMPLOYEE_ERROR'])
      history.push(`/employee-benefits/company-list/${match.params.companyId}/employee-list/${match.params.employeeId}`)
    }
  }, [updateEmployeeData])

  useEffect(() => {
    if (location.state && location.state) {
      const { state: employeeData } = location
      const values = form.getFieldsValue()
      if (employeeData && values) {
        for (const key in values.employee_data) {
          if (key !== 'dob' && key !== 'phone' && key !== 'effective_join_date') {
            form.setFieldsValue({
              [`employee_data.${key}`]: employeeData[key]
            })
          } else if (key === 'dob') {
            form.setFieldsValue({
              [`employee_data.${key}`]: moment(employeeData[key], 'YYYY-MM-DD')
            })
          } else if (key === 'phone') {
            form.setFieldsValue({
              [`employee_data.${key}`]: employeeData[key] ? formattedPhoneNumber(employeeData[key]) : ''
            })
          } else if (key === 'effective_join_date' && employeeData[key]) {
            form.setFieldsValue({
              [`employee_data.${key}`]: moment(employeeData[key], 'YYYY-MM-DD')
            })
          }
        }
      }
    }
  }, [location])

  return (
    <EbEmptyPage history={history}>
      <Spin
        spinning={!!UPDATE_EMPLOYEE_LOADER}
      >
        {UPDATE_EMPLOYEE_ERROR && (!updateEmployeeErrorData) && <Alert type='error' message={updateEmployeeStatus} banner />}
        <Title
          level={4}
        >
          Edit Employee
        </Title>
        <Form
          onSubmit={handleSubmit}
        >
          <RowWithMargin gutter={8}>
            <Col span={12}>
              <Form.Item
                hasFeedback
                label='Name'
              >
                {
                getFieldDecorator(
                  'employee_data.name',
                  EmployeeFormItemConfigs.name
                )(
                  <Input />
                )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                required
                hasFeedback
                label='Date of Birth'
              >
                {
                  getFieldDecorator(
                    'employee_data.dob',
                    EmployeeFormItemConfigs.dob
                  )(
                    <DatePicker
                      format='YYYY-MM-DD'
                    />
                  )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                required={isRequired}
                hasFeedback
                label='Effective Join Date'
              >
                {
                  getFieldDecorator(
                    'employee_data.effective_join_date',
                    EmployeeFormItemConfigs.effective_join_date(isRequired)
                  )(
                    <DatePicker
                      format='YYYY-MM-DD'
                    />
                  )
                }
              </Form.Item>
            </Col>
            <Col
              span={12}
            >
              <Form.Item
                hasFeedback
                label='Phone'
              >
                {
                  getFieldDecorator(
                    'employee_data.phone',
                    EmployeeFormItemConfigs.phone
                  )(
                    <Input
                      type='number'
                      addonBefore='+62'
                    />
                  )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                hasFeedback
                label='Department'
              >
                {
                  getFieldDecorator(
                    'employee_data.department',
                    EmployeeFormItemConfigs.department
                  )(
                    <Input />
                  )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                required
                hasFeedback
                label='Gender'
              >
                {
                  getFieldDecorator(
                    'employee_data.gender',
                    EmployeeFormItemConfigs.gender
                  )(
                    <Select>
                      <Option value='Perempuan'>Perempuan</Option>
                      <Option value='Laki-laki'>Laki-laki</Option>
                    </Select>
                  )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                hasFeedback
                label='Plan'
              >
                {
                  getFieldDecorator(
                    'employee_data.plan',
                    EmployeeFormItemConfigs.plan
                  )(
                    <Input />
                  )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                hasFeedback
                label='Email'
              >
                {
                  getFieldDecorator('employee_data.email',
                    EmployeeFormItemConfigs.email
                  )(
                    <Input />
                  )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                hasFeedback
                label='E-Card Company Name'
              >
                {
                  getFieldDecorator('employee_data.policy_data.company_name', {
                    validateTrigger: 'onBlur',
                    rules: editEmployeeValidations.company_name(form)
                  })(
                    <Input maxLength={55} />
                  )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                hasFeedback
                label='E-Card Policy Number'
              >
                {
                  getFieldDecorator('employee_data.policy_data.policy_number', {
                    validateTrigger: 'onBlur',
                    rules: editEmployeeValidations.policy_number(form)
                  })(
                    <Input maxLength={27} />
                  )
                }
              </Form.Item>
            </Col>
            <Col span={12}>
              <Form.Item
                hasFeedback
                label='E-Card Number'
              >
                {
                  getFieldDecorator('employee_data.policy_data.card_number', {
                    validateTrigger: 'onBlur',
                    rules: editEmployeeValidations.card_number(form)
                  })(
                    <Input maxLength={27} />
                  )
                }
              </Form.Item>
            </Col>
            <Divider />
          </RowWithMargin>
          <RowWithMargin>
            <ColTextAlignCenter span={24}>
              <Button type='primary' htmlType='submit'>Submit</Button>
            </ColTextAlignCenter>
          </RowWithMargin>
        </Form>
      </Spin>
    </EbEmptyPage>
  )
}
export default Form.create({ name: 'edit-employee-form' })(EmployeeDetail)
