import axios from 'axios'
import querySearchBuilder from '../../helpers/querySearchBuilder'
import { getHeader } from '../../helpers/utility'
import urlMapper from '../../helpers/urlMapper'

const uploadFile = ({
  url = '',
  uploadUrl = '',
  signedUrl = '',
  query = {},
  body = {},
  params = {},
  signedUrlBody = {},
  uploadBody = {},
  customReturnData = {},
  urlKey = 'document_url'
}) => {
  // TODO: 1. take signed url body in parameters
  // 2. take upload body in parameters
  // 3. take any added return value in data from parameters
  const queryString = querySearchBuilder(query)
  // const mappedUrl = urlMapper(url, params)
  // const combinedUrl = `${mappedUrl}${queryString}`
  const mappedUrlSigned = urlMapper(signedUrl, params)
  const combinedSignedUrl = `${mappedUrlSigned}${queryString}`
  const mappedUploadUrl = urlMapper(uploadUrl, params)
  const combinedUploadUrl = `${mappedUploadUrl}`
  // let getSignedUrlBody = { company_id: body.companyId, document_type: body.documentType }
  return axios
    .post(combinedSignedUrl, signedUrlBody, { headers: getHeader() })
    .then(response => {
      const { data } = response
      return axios.put(data.signed_url, body.file, { headers: { 'Content-type': body.file.type } })
        .then(res => {
        // TODO: post on backend here
          return axios.post(combinedUploadUrl, { [urlKey]: data.url, ...uploadBody }, { headers: getHeader() })
            .then(res => {
              for (const key in customReturnData) {
                res.data[key] = customReturnData[key]
              }
              return res
            })
            .catch(error => {
              if (error.response) {
                throw error.response
              } else {
                throw error
              }
            })
        })
        .catch(error => {
          if (error.response) {
            throw error.response
          } else {
            throw error
          }
        })
    })
    .catch(error => {
      if (error.response) {
        throw error.response
      } else {
        throw error
      }
    })
}

export default uploadFile
