import { useServiceRequest, useResetError } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useUpdateEmployee = () => {
  const [{ updateEmployeeData, updateEmployeeStatus }, dispatch] = useEBContextValue()
  const { resetError } = useResetError()
  const [callApi] = useServiceRequest(dispatch)

  const updateEmployeeRequest = (payload = {}) => {
    resetError(['UPDATE_EMPLOYEE_ERROR'])
    callApi(actions.updateEmployee({ body: payload }))
  }
  return { updateEmployeeData, updateEmployeeStatus, updateEmployeeRequest }
}
